type CartItem = { name: string; price: number; qty: number };
type Cart = CartItem[];
type Currency = "CNY" | "USD";

function total(cart: Cart): number {
  return cart.reduce((s, it) => s + it.price * it.qty, 0);
}
function addItem(cart: Cart, item: CartItem): Cart {
  return [...cart, item];
}
function formatPrice(n: number, c: Currency): string {
  return c === "CNY" ? `￥${n}` : `$${n}`;
}

