type ApiResult<T> =
  | { ok: true; data: T }
  | { ok: false; error: string };

function unwrap<T>(r: ApiResult<T>): T {
  if (r.ok) return r.data;
  throw new Error(r.error);
}

function getProp<T, K extends keyof T>(obj: T, key: K): T[K] {
